+    expect(pageOfOrdinal(pages, 1)).toBe(0);
+    expect(pageOfOrdinal(pages, 3)).toBe(1);
+  });
+  it("returns -1 for a missing ordinal", () => {
+    expect(pageOfOrdinal(pages, 9)).toBe(-1);
+  });
